function minPathSum(grid) {
  const memo = new Map();
  const best = (r, c) => {                       // the cheapest path sum to (r, c)
    if (r < 0 || c < 0) return Infinity;         // off the grid: never chosen
    if (r === 0 && c === 0) return grid[0][0];
    const key = r * grid[0].length + c;
    if (!memo.has(key)) memo.set(key, grid[r][c] + Math.min(best(r - 1, c), best(r, c - 1)));
    return memo.get(key);
  };
  return best(grid.length - 1, grid[0].length - 1);
}

from functools import cache

def min_path_sum(grid):
    @cache
    def best(r, c):                       # the cheapest path sum to (r, c)
        if r < 0 or c < 0:
            return float("inf")           # off the grid: never chosen
        if r == 0 and c == 0:
            return grid[0][0]
        return grid[r][c] + min(best(r - 1, c), best(r, c - 1))
    return best(len(grid) - 1, len(grid[0]) - 1)

