int best(int[][] grid, int r, int c) {           // the cheapest path sum to (r, c)
    if (r < 0 || c < 0) return Integer.MAX_VALUE;   // off the grid: never chosen
    if (r == 0 && c == 0) return grid[0][0];
    if (memo[r][c] != null) return memo[r][c];
    return memo[r][c] = grid[r][c] + Math.min(best(grid, r - 1, c), best(grid, r, c - 1));
