function minPathSum(grid) {
  const n = grid[0].length;
  const row = new Array(n).fill(Infinity);
  row[0] = 0;
  for (const cells of grid) {
    row[0] += cells[0];                                     // left column: only from above
    for (let c = 1; c < n; c++) row[c] = cells[c] + Math.min(row[c], row[c - 1]);   // above or left
  }
  return row[n - 1];
}

def min_path_sum(grid):
    n = len(grid[0])
    row = [float("inf")] * n
    row[0] = 0
    for cells in grid:
        row[0] += cells[0]                # left column: only from above
