int minPathSum(int[][] grid) {
    int n = grid[0].length;
    long[] row = new long[n];
    Arrays.fill(row, Long.MAX_VALUE / 2);
    row[0] = 0;
    for (int[] cells : grid) {
        row[0] += cells[0];                                   // left column: only from above
        for (int c = 1; c < n; c++) row[c] = cells[c] + Math.min(row[c], row[c - 1]);   // above or left
    }
    return (int) row[n - 1];
}

